actions.script:
String imgPath = sri.screenUrlInfo.extraPathNameList.join("/")
String resLocation = "component://zenith-erp-app/screen/zenithstatic/img/" + imgPath
if (imgPath.endsWith(".svg")) {
    def resRef = ec.resource.getLocationReference(resLocation)
    if (resRef != null && resRef.supportsExists() && resRef.exists) {
        ec.web.response.setContentType("image/svg+xml")
        ec.web.response.setCharacterEncoding("UTF-8")
        def os = ec.web.response.outputStream
        def is = resRef.openStream()
        try { byte[] buf = new byte[4096]; int n; while ((n = is.read(buf)) != -1) os.write(buf, 0, n) }
        finally { is.close(); os.flush() }
    }
} else {
    ec.web.sendResourceResponse(resLocation, true)
}
